window.AUTH=window.AUTH||{};window.AUTH["23-1038"]={"d":"23-1038","id":"2024/23-1038","n":"FDA v. Wages and White Lion Investments, L.L.C.","briefs":[{"k":"petitioner","label":"Brief of petitioner Food and Drug Administration","date":"2024-08-26","url":"https://www.supremecourt.gov/DocketPDF/23/23-1038/323413/20240826164114741_23-1038tsFDA.pdf","side":"pet","n":61},{"k":"respondent","label":"Brief of respondents Wages and White Lion Investments, L.L.C., dba Triton Distribution, et al.","date":"2024-10-07","url":"https://www.supremecourt.gov/DocketPDF/23/23-1038/327672/20241007153644875_23-1038%20Brief%20for%20Respondents.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioner Food and Drug Administration","date":"2024-11-06","url":"https://www.supremecourt.gov/DocketPDF/23/23-1038/331324/20241106154759342_23-1038rbUnitedStates.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r22_ed9g.pdf","tr":true,"items":[{"t":"case","label":"American Manufacturers Mutual Ins. Co. v. Sullivan","cite":"526 U.S. 40","y":1999,"id":"1998/97-2000","sc":1,"sum":"Further, under Pennsylvania law no due process protection attaches to payment of disputed medical expenses before the reasonableness and necessity of those expenses is determined. The Act does not entitle an employee to payment of all medical treatment, but only that treatment which is reasonable and necessary.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Avail Vapor, LLC v. FDA","cite":"55 F.4th 409","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/409/","by":{"0":"17, 21, 23, 32, 37, 43, 46","2":"6, 7, 12, 22"}},{"t":"case","label":"Bidi Vapor LLC v. FDA","cite":"47 F.4th 1191","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/47/1191/","ar":3,"by":{"0":"37","1":"51, 53-56"}},{"t":"case","label":"Bowles v. Seminole Rock & Sand Co.","cite":"325 U.S. 410","y":1945,"id":"scdb/1944-069","sc":1,"by":{"0":"29"}},{"t":"case","label":"Burlington Truck Lines, Inc. v. United States","cite":"371 U.S. 156","y":1962,"id":"1962/27","sc":1,"sum":"The judgment is reversed and the case is remanded to the District Court with instructions to set aside the Commission's order and remand the case to the Commission for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40, 41","1":"50"}},{"t":"case","label":"Calcutt v. FDIC","cite":"598 U.S. 623","y":2023,"id":"2022/22-714","sc":1,"op":13,"ar":2,"sum":"After determining that the FDIC had made two legal errors in adjudicating petitioner’s case, the Sixth Circuit’s proper course was to remand the matter back to the FDIC for further consideration; the Sixth Circuit erred by conducting its own review of the record and affirming the FDIC’s sanctions against petitioner based on a legal rationale different from the one adopted by the FDIC.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40-42","1":"52, 55","2":"16, 17"}},{"t":"case","label":"Cheek v. United States","cite":"498 U.S. 192","y":1991,"id":"1990/89-658","sc":1,"sum":"Petitioner Cheek was charged with six counts of willfully failing to file a federal income tax return in violation of § 7203 of the Internal Revenue Code (Code) and three counts of willfully attempting to evade his income taxes in violation of §7201. Although admitting that he had not filed his returns, he testified that he had not acted willfully because he sincerely believed, based on his indoctrination by a group …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"0":"30, 31","1":"28"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 30"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"0":"37","1":"35"}},{"t":"case","label":"DHS v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Department of Commerce v. New York","cite":"588 U.S. 752","y":2019,"id":"2018/18-966","sc":1,"op":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 40, 45","2":"13, 16, 17, 21, 22"}},{"t":"case","label":"Electric Clouds, Inc. v. FDA","cite":"94 F.4th 950","y":2024,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/94/950/","by":{"0":"17, 22, 23, 32, 37, 41, 43, 46","2":"6, 9, 11-13"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"op":11,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"0":"18, 30","1":"28, 35, 42"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"592 U.S. 414","y":2021,"id":"2020/19-1231","sc":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15-17","1":"46"}},{"t":"case","label":"General Electric Co. v. EPA","cite":"53 F.3d 1324","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/53/1324/","by":{"0":"27","1":"28, 35","2":"3"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"sum":"1. Antipicketing ordinance, virtually identical with one invalidated as violative of equal protection in Police Department of Chicago v. Mosley, ante, p. 92, is likewise invalid.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Gripum LLC v. FDA","cite":"47 F.4th 553","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/47/553/","by":{"0":"17, 23, 43, 44, 46"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"27","2":"3"}},{"t":"case","label":"Kisor v. Wilkie","cite":"588 U.S. 558","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29"}},{"t":"case","label":"Liquid Labs LLC v. FDA","cite":"52 F.4th 533","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/52/533/","by":{"0":"17, 21-23, 32, 37, 43, 46","2":"6, 12, 14"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"591 U.S. 657","y":2020,"id":"2019/19-431","sc":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"0":"39","1":"55","2":"15, 16"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"ar":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 29, 30","1":"44, 45"}},{"t":"case","label":"Lotus Vaping Technologies, LLC v. FDA","cite":"73 F.4th 657","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/73/657/","by":{"0":"17, 21, 23, 32, 37, 43, 46","1":"37","2":"6"}},{"t":"case","label":"Magellan Technology, Inc. v. FDA","cite":"70 F.4th 622","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/70/622/","by":{"0":"17, 21, 32, 37, 46","2":"12"}},{"t":"case","label":"Morgan Stanley Capital Group Inc. v. Public Utility Dist. No. 1","cite":"554 U.S. 527","y":2008,"id":"2007/06-1457","sc":1,"op":1,"sum":"Renegotiation is allowed only if the contract poses \"serious harm to the public interest.\" In this case, the Court decided 5-2 (Justices John G. Roberts and Stephen Breyer took no part in the decision) that the Federal Energy Regulatory Commission had failed to make sufficient factual findings in order to determine whether such serious harm could in fact occur.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","2":"4, 5"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Ohio v. EPA","cite":"144 S. Ct. 2040","y":2024,"url":"https://www.courtlistener.com/c/S.%20Ct./144/2040/","sc":1,"by":{"0":"39"}},{"t":"case","label":"Perez v. Mortgage Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Prohibition Juice Co. v. FDA","cite":"45 F.4th 8","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/45/8/","by":{"0":"18, 22, 23, 32, 37, 43, 46","1":"37, 55, 56","2":"2, 6, 9, 11, 12, 15"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"op":2,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","2":"16, 17"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"op":4,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"34"}},{"t":"case","label":"Shinseki v. Sanders","cite":"556 U.S. 396","y":2009,"id":"2008/07-1209","sc":1,"op":10,"ar":1,"sum":"The Court found that the lower court's framework for evaluating VA (Veterans' Affairs) notice errors conflicted with the established law that the Veterans Court \"take due account of the rule of the prejudicial error.\"","sumSrc":"Oyez","by":{"0":"37, 39, 41","1":"51, 52, 55"}},{"t":"case","label":"United States v. L. Cohen Grocery Co.","cite":"255 U.S. 81","y":1921,"id":"scdb/1920-161","sc":1,"sum":"1. Section 4 of the Food Control Act of August 10, 1917, as amended October 22, 1919, in denouncing and attaching a penalty of fine or imprisonment to the making by any person of “any unjust or unreasonable rate or charge in handling or dealing in or with any necessaries,” must be construed” as forbidding and penalizing the exaction of an excessive price upon the sale of a commodity.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. NRDC, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","2":"4"}},{"t":"case","label":"Waters-Pierce Oil Co. v. Texas","cite":"212 U.S. 86","y":1909,"id":"scdb/1908-063","sc":1,"sum":"The jurisdiction of this court, under § 709 Rev. Stat., to review the proceedings of state courts is limited to specific instances of denials of Federal rights specially set up in and denied by the state court.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"27, 28","1":"34, 35"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"head":"§551. Definitions","tname":"Government Organization and Employees","by":{"0":"4","1":"47, 47"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)(4)(A)"],"stext":{"head":"§553. Rule making","paras":[[0,"(a) This section applies, according to the provisions thereof, except to the extent that there is involved—"],[1,"(1) a military or foreign affairs function of the United States; or"],[1,"(2) a matter relating to agency management or personnel or to public property, loans, grants, benefits, or contracts."],[0,"(b) General notice of proposed rule making shall be published in the Federal Register, unless persons subject thereto are named and either personally served or otherwise have actual notice thereof in accordance with law. The notice shall include—"],[1,"(1) a statement of the time, place, and nature of public rule making proceedings;"],[1,"(2) reference to the legal authority under which the rule is proposed;"],[1,"(3) either the terms or substance of the proposed rule or a description of the subjects and issues involved; and"],[1,"(4) the Internet address of a summary of not more than 100 words in length of the proposed rule, in plain language, that shall be posted on the Internet website under section 206(d) of the E-Government Act of 2002 (44 U.S.C. 3501 note) (commonly known as regulations.gov)."],[0,"Except when notice or hearing is required by statute, this subsection does not apply—"],[1,"(A) to interpretative rules, general statements of policy, or rules of agency organization, procedure, or practice; or"],[1,"(B) when the agency for good cause finds (and incorporates the finding and a brief statement of reasons therefor in the rules issued) that notice and public procedure thereon are impracticable, unnecessary, or contrary to the public interest."],[0,"(c) After notice required by this section, the agency shall give interested persons an opportunity to participate in the rule making through submission of written data, views, or arguments with or without opportunity for oral presentation. After consideration of the relevant matter presented, the agency shall incorporate in the rules adopted a concise general statement of their basis and purpose. When rules are required by statute to be made on the record after opportunity for an agency hearing, sections 556 and 557 of this title apply instead of this subsection."],[0,"(d) The required publication or service of a substantive rule shall be made not less than 30 days before its effective date, except—"],[1,"(1) a substantive rule which grants or recognizes an exemption or relieves a restriction;"],[1,"(2) interpretative rules and statements of policy; or"],[1,"(3) as otherwise provided by the agency for good cause found and published with the rule."],[0,"(e) Each agency shall give an interested person the right to petition for the issuance, amendment, or repeal of a rule."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/553?type=usc&year=mostrecent&link-type=html"},"head":"§553. Rule making","tname":"Government Organization and Employees","by":{"0":"26","1":"48, 48"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"2, 2","1":"35, 51","2":"15"}},{"t":"usc","label":"15 U.S.C. § 57b-4","url":"https://www.law.cornell.edu/uscode/text/15/57b-4","subs":["(b)"],"by":{"0":"29"}},{"t":"usc","label":"21 U.S.C. § 387a","url":"https://www.law.cornell.edu/uscode/text/21/387a","subs":["(b)"],"stext":{"head":"§387a. FDA authority over tobacco products","paras":[[0,"(a) In general"],[0,"Tobacco products, including modified risk tobacco products for which an order has been issued in accordance with section 387k of this title, shall be regulated by the Secretary under this subchapter and shall not be subject to the provisions of subchapter V."],[0,"(b) Applicability"],[0,"This subchapter shall apply to all cigarettes, cigarette tobacco, roll-your-own tobacco, and smokeless tobacco and to any other tobacco products that the Secretary by regulation deems to be subject to this subchapter. This subchapter shall also apply to any tobacco product containing nicotine that is not made or derived from tobacco."],[0,"(c) Scope"],[0,"(1) In general"],[1,"Nothing in this subchapter, or any policy issued or regulation promulgated thereunder, or in sections 101(a), 102, or 103 of title I, title II, or title III of the Family Smoking Prevention and Tobacco Control Act, shall be construed to affect, expand, or limit the Secretary's authority over (including the authority to determine whether products may be regulated), or the regulation of, products under this chapter that are not tobacco products under subchapter V or any other subchapter."],[0,"(2) Limitation of authority"],[0,"(A) In general"],[2,"The provisions of this subchapter shall not apply to tobacco leaf that is not in the possession of a manufacturer of tobacco products, or to the producers of tobacco leaf, including tobacco growers, tobacco warehouses, and tobacco grower cooperatives, nor shall any employee of the Food and Drug Administration have any authority to enter onto a farm owned by a producer of tobacco leaf without the written consent of such producer."],[0,"(B) Exception"],[2,"Notwithstanding subparagraph (A), if a producer of tobacco leaf is also a tobacco product manufacturer or controlled by a tobacco product manufacturer, the producer shall be subject to this subchapter in the producer's capacity as a manufacturer. The exception in this subparagraph shall not apply to a producer of tobacco leaf who grows tobacco under a contract with a tobacco product manufacturer and who is not otherwise engaged in the manufacturing process."],[0,"(C) Rule of construction"],[2,"Nothing in this subchapter shall be construed to grant the Secretary authority to promulgate regulations on any matter that involves the production of tobacco leaf or a producer thereof, other than activities by a manufacturer affecting production."],[0,"(d) Rulemaking procedures"],[0,"Each rulemaking under this subchapter shall be in accordance with chapter 5 of title 5. This subsection shall not be construed to affect the rulemaking provisions of section 102(a) of the Family Smoking Prevention and Tobacco Control Act [21 U.S.C. 387a–1(a)]."],[0,"(e) Center for tobacco products"],[0,"Not later than 90 days after June 22, 2009, the Secretary shall establish within the Food and Drug Administration the Center for Tobacco Products, which shall report to the Commissioner of Food and Drugs in the same manner as the other agency centers within the Food and Drug Administration. The Center shall be responsible for the implementation of this subchapter and related matters assigned by the Commissioner."],[0,"(f) Office to assist small tobacco product manufacturers"],[0,"The Secretary shall establish within the Food and Drug Administration an identifiable office to provide technical and other nonfinancial assistance to small tobacco product manufacturers to assist them in complying with the requirements of this chapter."],[0,"(g) Consultation prior to rulemaking"],[0,"Prior to promulgating rules under this subchapter, the Secretary shall endeavor to consult with other Federal agencies as appropriate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§387a. FDA authority over tobacco products","tname":"Food and Drugs","by":{"0":"3, 5","1":"9"}},{"t":"usc","label":"21 U.S.C. § 387j","url":"https://www.law.cornell.edu/uscode/text/21/387j","subs":["(a)(1)","(a)(2)(A)","(c)(2)","(c)(2)(A)","(c)(4)","(c)(4)(A)","(c)(4)(B)","(c)(5)(A)","(c)(5)(B)","(b)(1)(A)"],"stext":{"head":"§387j. Application for review of certain tobacco products","paras":[[0,"(a) In general"],[0,"(1) New tobacco product defined"],[1,"For purposes of this section the term \"new tobacco product\" means—"],[2,"(A) any tobacco product (including those products in test markets) that was not commercially marketed in the United States as of February 15, 2007; or"],[2,"(B) any modification (including a change in design, any component, any part, or any constituent, including a smoke constituent, or in the content, delivery or form of nicotine, or any other additive or ingredient) of a tobacco product where the modified product was commercially marketed in the United States after February 15, 2007."],[0,"(2) Premarket review required"],[0,"(A) New products"],[2,"An order under subsection (c)(1)(A)(i) for a new tobacco product is required unless—"],[3,"(i) the manufacturer has submitted a report under section 387e(j) of this title; and the Secretary has issued an order that the tobacco product—"],[4,"(I) is substantially equivalent to a tobacco product commercially marketed (other than for test marketing) in the United States as of February 15, 2007; and"],[4,"(II) is in compliance with the requirements of this chapter; or"],[3,"(ii) the tobacco product is exempt from the requirements of section 387e(j) of this title pursuant to a regulation issued under section 387e(j)(3) of this title."],[0,"(B) Application to certain post-February 15, 2007, products"],[2,"Subparagraph (A) shall not apply to a tobacco product—"],[3,"(i) that was first introduced or delivered for introduction into interstate commerce for commercial distribution in the United States after February 15, 2007, and prior to the date that is 21 months after June 22, 2009; and"],[3,"(ii) for which a report was submitted under section 387e(j) of this title within such 21-month period,"],[2,"except that subparagraph (A) shall apply to the tobacco product if the Secretary issues an order that the tobacco product is not substantially equivalent."],[0,"(3) Substantially equivalent defined"],[0,"(A) In general"],[2,"In this section and section 387e(j) of this title, the term \"substantially equivalent\" or \"substantial equivalence\" means, with respect to the tobacco product being compared to the predicate tobacco product, that the Secretary by order has found that the tobacco product—"],[3,"(i) has the same characteristics as the predicate tobacco product; or"],[3,"(ii) has different characteristics and the information submitted contains information, including clinical data if deemed necessary by the Secretary, that demonstrates that it is not appropriate to regulate the product under this section because the product does not raise different questions of public health."],[0,"(B) Characteristics"],[2,"In subparagraph (A), the term \"characteristics\" means the materials, ingredients, design, composition, heating source, or other features of a tobacco product."],[0,"(C) Limitation"],[2,"A tobacco product may not be found to be substantially equivalent to a predicate tobacco product that has been removed from the market at the initiative of the Secretary or that has been determined by a judicial order to be misbranded or adulterated."],[0,"(4) Health information"],[0,"(A) Summary"],[2,"As part of a submission under section 387e(j) of this title respecting a tobacco product, the person required to file a premarket notification under such section shall provide an adequate summary of any health information related to the tobacco product or state that such information will be made available upon request by any person."],[0,"(B) Required information"],[2,"Any summary under subparagraph (A) respecting a tobacco product shall contain detailed information regarding data concerning adverse health effects and shall be made available to the public by the Secretary within 30 days of the issuance of a determination that such tobacco product is substantially equivalent to another tobacco product."],[0,"(b) Application"],[0,"(1) Contents"],[1,"An application under this section shall contain—"],[2,"(A) full reports of all information, published or known to, or which should reasonably be known to, the applicant, concerning investigations which have been made to show the health risks of such tobacco product and whether such tobacco product presents less risk than other tobacco products;"],[2,"(B) a full statement of the components, ingredients, additives, and properties, and of the principle or principles of operation, of such tobacco product;"],[2,"(C) a full description of the methods used in, and the facilities and controls used for, the manufacture, processing, and, when relevant, packing and installation of, such tobacco product;"],[2,"(D) an identifying reference to any tobacco product standard under section 387g of this title which would be applicable to any aspect of such tobacco product, and either adequate information to show that such aspect of such tobacco product fully meets such tobacco product standard or adequate information to justify any deviation from such standard;"],[2,"(E) such samples of such tobacco product and of components thereof as the Secretary may reasonably require;"],[2,"(F) specimens of the labeling proposed to be used for such tobacco product; and"],[2,"(G) such other information relevant to the subject matter of the application as the Secretary may require."],[0,"(2) Referral to Tobacco Products Scientific Advisory Committee"],[1,"Upon receipt of an application meeting the requirements set forth in paragraph (1), the Secretary—"],[2,"(A) may, on the Secretary's own initiative; or"],[2,"(B) may, upon the request of an applicant,"],[1,"refer such application to the Tobacco Products Scientific Advisory Committee for reference and for submission (within such period as the Secretary may establish) of a report and recommendation respecting the application, together with all underlying data and the reasons or basis for the recommendation."],[0,"(c) Action on application"],[0,"(1) Deadline"],[0,"(A) In general"],[2,"As promptly as possible, but in no event later than 180 days after the receipt of an application under subsection (b), the Secretary, after considering the report and recommendation submitted under subsection (b)(2), shall—"],[3,"(i) issue an order that the new product may be introduced or delivered for introduction into interstate commerce if the Secretary finds that none of the grounds specified in paragraph (2) of this subsection applies; or"],[3,"(ii) issue an order that the new product may not be introduced or delivered for introduction into interstate commerce if the Secretary finds (and sets forth the basis for such finding as part of or accompanying such denial) that 1 or more grounds for denial specified in paragraph (2) of this subsection apply."],[0,"(B) Restrictions on sale and distribution"],[2,"An order under subparagraph (A)(i) may require that the sale and distribution of the tobacco product be restricted but only to the extent that the sale and distribution of a tobacco product may be restricted under a regulation under section 387f(d) of this title."],[0,"(2) Denial of application"],[1,"The Secretary shall deny an application submitted under subsection (b) if, upon the basis of the information submitted to the Secretary as part of the application and any other information before the Secretary with respect to such tobacco product, the Secretary finds that—"],[2,"(A) there is a lack of a showing that permitting such tobacco product to be marketed would be appropriate for the protection of the public health;"],[2,"(B) the methods used in, or the facilities or controls used for, the manufacture, processing, or packing of such tobacco product do not conform to the requirements of section 387f(e) of this title;"],[2,"(C) based on a fair evaluation of all material facts, the proposed labeling is false or misleading in any particular; or"],[2,"(D) such tobacco product is not shown to conform in all respects to a tobacco product standard in effect under section 387g of this title, and there is a lack of adequate information to justify the deviation from such standard."],[0,"(3) Denial information"],[1,"Any denial of an application shall, insofar as the Secretary determines to be practicable, be accompanied by a statement informing the applicant of the measures required to remove such application from deniable form (which measures may include further research by the applicant in accordance with 1 or more protocols prescribed by the Secretary)."],[0,"(4) Basis for finding"],[1,"For purposes of this section, the finding as to whether the marketing of a tobacco product for which an application has been submitted is appropriate for the protection of the public health shall be determined with respect to the risks and benefits to the population as a whole, including users and nonusers of the tobacco product, and taking into account—"],[2,"(A) the increased or decreased likelihood that existing users of tobacco products will stop using such products; and"],[2,"(B) the increased or decreased likelihood that those who do not use tobacco products will start using such products."],[0,"(5) Basis for action"],[0,"(A) Investigations"],[2,"For purposes of paragraph (2)(A), whether permitting a tobacco product to be marketed would be appropriate for the protection of the public health shall, when appropriate, be determined on the basis of well-controlled investigations, which may include 1 or more clinical investigations by experts qualified by training and experience to evaluate the tobacco product."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387j?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§387j. Application for review of certain tobacco products","tname":"Food and Drugs","by":{"0":"26, 26, 26, 26, 26, 26, 26, 26, 26","1":"3, 9, 3, 4, 49","2":"4, 7, 7, 6, 8"}},{"t":"usc","label":"21 U.S.C. § 387k","url":"https://www.law.cornell.edu/uscode/text/21/387k","subs":["(l)(1)"],"by":{"0":"26"}},{"t":"usc","label":"21 U.S.C. § 387l","url":"https://www.law.cornell.edu/uscode/text/21/387l","subs":["(a)(1)(B)","(b)"],"by":{"0":"3, 3"}},{"t":"usc","label":"21 U.S.C. § 393","url":"https://www.law.cornell.edu/uscode/text/21/393","subs":["(d)(2)"],"by":{"0":"3"}},{"t":"usc","label":"29 U.S.C. § 259","url":"https://www.law.cornell.edu/uscode/text/29/259","subs":["(a)"],"by":{"0":"29"}},{"t":"usc","label":"52 U.S.C. § 30111","url":"https://www.law.cornell.edu/uscode/text/52/30111","subs":["(e)"],"by":{"0":"29"}},{"t":"reg","label":"81 Fed. Reg. 28,974","url":"https://www.govinfo.gov/link/fr/81/28974","by":{"0":"5","1":"9, 10"}},{"t":"reg","label":"84 Fed. Reg. 50,566","url":"https://www.govinfo.gov/link/fr/84/50566","by":{"0":"33","1":"12, 31, 32, 41, 49, 50"}},{"t":"case","label":"Am. Acad. of Pediatrics v. FDA","cite":"399 F. Supp. 3d 479","y":2019,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/399/479/","op":1,"by":{"1":"10","2":"22"}},{"t":"case","label":"Appalachian Power Co. v. EPA","cite":"208 F.3d 1015","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/208/1015/","by":{"1":"31"}},{"t":"case","label":"DHS v. Regents of the Univ. of Cal.","cite":"591 U.S. 1","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/1/","sc":1,"op":1,"by":{"1":"39, 41-43, 55"}},{"t":"case","label":"Dep’t of Commerce v. New York","cite":"588 U.S. 752","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/752/","sc":1,"op":1,"by":{"1":"55"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"579 U.S. 211","y":2016,"id":"2015/15-415","sc":1,"op":6,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"1":"40, 42, 46"}},{"t":"case","label":"ExxonMobil Pipeline Co. v. United States DOT","cite":"867 F.3d 564","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/564/","by":{"1":"28","2":"3"}},{"t":"case","label":"March v. Or. Nat. Res. Council","cite":"490 U.S. 360","y":1989,"id":"1988/87-1704","sc":1,"sum":"The Elk Creek Dam is part of a three-dam project designed to control the water supply in Oregon's Rogue River Basin. The Army Corps of Engineers (Corps) completed an Environmental Impact Statement (EIS) for the Elk Creek project in 1971, and, in 1980, released its final Environmental Impact Statement, Supplement No. 1 (FEISS). Since the Rogue River is a premier fishing ground, the FEISS paid special heed to water …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Martin v. OSHRC","cite":"499 U.S. 144","y":1991,"id":"1990/89-1541","sc":1,"sum":"A reviewing court should defer to the Secretary when the Secretary and the Commission furnish reasonable but conflicting interpretations of an ambiguous regulation promulgated by the Secretary under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"1":"55"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"op":4,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"1":"50, 57"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. U.S. Army Corp of Eng’rs","cite":"417 F.3d 1272","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/417/1272/","by":{"1":"48"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"1":"34, 35"}},{"t":"case","label":"Radio Athens, Inc. v. FCC","cite":"401 F.2d 398","y":1968,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/401/398/","by":{"1":"34","2":"3"}},{"t":"case","label":"R.J. Reynolds Vapor Co. v. FDA","cite":"65 F.4th 182","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/65/182/","by":{"1":"48, 49"}},{"t":"case","label":"Rollins Env’t Servs. (NJ), Inc. v. EPA","cite":"937 F.2d 649","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/937/649/","by":{"1":"28"}},{"t":"case","label":"Safari Club Int’l v. Zinke","cite":"878 F.3d 316","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/878/316/","by":{"1":"48"}},{"t":"case","label":"Salzer v. FCC","cite":"778 F.2d 869","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/778/869/","ar":2,"by":{"1":"44"}},{"t":"case","label":"Satellite Broadcasting Co. v. FCC","cite":"824 F.2d 1","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/824/1/","by":{"1":"29, 35, 44","2":"3, 4"}},{"t":"case","label":"St. Vincent Randolph Hosp., Inc. v. Price","cite":"869 F.3d 510","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/510/","by":{"1":"55"}},{"t":"case","label":"Syncor Int’l Corp. v. Shalala","cite":"127 F.3d 90","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/127/90/","by":{"1":"48"}},{"t":"case","label":"Thigpen v. Roberts","cite":"468 U.S. 27","y":1984,"id":"1983/82-1330","sc":1,"sum":"Following an accident in which he lost control of his car and collided with a pickup truck, killing a passenger in the truck, respondent was charged with four misdemeanors-reckless driving, driving while his license was revoked, driving on the wrong side of the road, and driving while intoxicated. Upon being convicted of these charges in a Mississippi Justice of the Peace Court, he appealed, and the case was …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Vapor Technology Ass’n v. FDA","cite":"977 F.3d 496","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/977/496/","op":2,"by":{"1":"10"}},{"t":"law","label":"Family Smoking Prevention and Tobacco Control Act, Pub. L. No. 111-31","url":"https://www.govinfo.gov/link/plaw/111/public/31","by":{"1":"3","2":"1"}},{"t":"usc","label":"21 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/21/321","subs":["(rr)(1)(2010)","(rr)(1)(2022)"],"by":{"1":"9, 9"}},{"t":"usc","label":"21 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/21/331","subs":["(a)"],"by":{"1":"9, 43"}},{"t":"usc","label":"21 U.S.C. § 333","url":"https://www.law.cornell.edu/uscode/text/21/333","subs":["(a)(1)","(f)(9)"],"by":{"1":"9, 43, 9, 43"}},{"t":"usc","label":"21 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/21/371","subs":["(h)(1)(C)(i)"],"by":{"1":"48"}},{"t":"usc","label":"21 U.S.C. § 387b","url":"https://www.law.cornell.edu/uscode/text/21/387b","subs":["(6)(A)"],"by":{"1":"9, 43"}},{"t":"usc","label":"21 U.S.C. § 387g","url":"https://www.law.cornell.edu/uscode/text/21/387g","subs":["(a)(1)(A)","(a)(4)(B)(i)","(c)","(d)"],"stext":{"head":"§387g. Tobacco product standards","paras":[[0,"(a) In general"],[0,"(1) Special rules"],[0,"(A) Special rule for cigarettes"],[2,"Beginning 3 months after June 22, 2009, a cigarette or any of its component parts (including the tobacco, filter, or paper) shall not contain, as a constituent (including a smoke constituent) or additive, an artificial or natural flavor (other than tobacco or menthol) or an herb or spice, including strawberry, grape, orange, clove, cinnamon, pineapple, vanilla, coconut, licorice, cocoa, chocolate, cherry, or coffee, that is a characterizing flavor of the tobacco product or tobacco smoke. Nothing in this subparagraph shall be construed to limit the Secretary's authority to take action under this section or other sections of this chapter applicable to menthol or any artificial or natural flavor, herb, or spice not specified in this subparagraph."],[0,"(B) Additional special rule"],[2,"Beginning 2 years after June 22, 2009, a tobacco product manufacturer shall not use tobacco, including foreign grown tobacco, that contains a pesticide chemical residue that is at a level greater than is specified by any tolerance applicable under Federal law to domestically grown tobacco."],[0,"(2) Revision of tobacco product standards"],[1,"The Secretary may revise the tobacco product standards in paragraph (1) in accordance with subsection (c)."],[0,"(3) Tobacco product standards"],[0,"(A) In general"],[2,"The Secretary may adopt tobacco product standards in addition to those in paragraph (1) if the Secretary finds that a tobacco product standard is appropriate for the protection of the public health."],[0,"(B) Determinations"],[0,"(i) Considerations"],[3,"In making a finding described in subparagraph (A), the Secretary shall consider scientific evidence concerning—"],[4,"(I) the risks and benefits to the population as a whole, including users and nonusers of tobacco products, of the proposed standard;"],[4,"(II) the increased or decreased likelihood that existing users of tobacco products will stop using such products; and"],[4,"(III) the increased or decreased likelihood that those who do not use tobacco products will start using such products."],[0,"(ii) Additional considerations"],[3,"In the event that the Secretary makes a determination, set forth in a proposed tobacco product standard in a proposed rule, that it is appropriate for the protection of public health to require the reduction or elimination of an additive, constituent (including a smoke constituent), or other component of a tobacco product because the Secretary has found that the additive, constituent, or other component is or may be harmful, any party objecting to the proposed standard on the ground that the proposed standard will not reduce or eliminate the risk of illness or injury may provide for the Secretary's consideration scientific evidence that demonstrates that the proposed standard will not reduce or eliminate the risk of illness or injury."],[0,"(4) Content of tobacco product standards"],[1,"A tobacco product standard established under this section for a tobacco product—"],[2,"(A) shall include provisions that are appropriate for the protection of the public health, including provisions, where appropriate—"],[3,"(i) for nicotine yields of the product;"],[3,"(ii) for the reduction or elimination of other constituents, including smoke constituents, or harmful components of the product; or"],[3,"(iii) relating to any other requirement under subparagraph (B);"],[2,"(B) shall, where appropriate for the protection of the public health, include—"],[3,"(i) provisions respecting the construction, components, ingredients, additives, constituents, including smoke constituents, and properties of the tobacco product;"],[3,"(ii) provisions for the testing (on a sample basis or, if necessary, on an individual basis) of the tobacco product;"],[3,"(iii) provisions for the measurement of the tobacco product characteristics of the tobacco product;"],[3,"(iv) provisions requiring that the results of each or of certain of the tests of the tobacco product required to be made under clause (ii) show that the tobacco product is in conformity with the portions of the standard for which the test or tests were required; and"],[3,"(v) a provision requiring that the sale and distribution of the tobacco product be restricted but only to the extent that the sale and distribution of a tobacco product may be restricted under a regulation under section 387f(d) of this title;"],[2,"(C) shall, where appropriate, require the use and prescribe the form and content of labeling for the proper use of the tobacco product; and"],[2,"(D) shall require tobacco products containing foreign-grown tobacco to meet the same standards applicable to tobacco products containing domestically grown tobacco."],[0,"(5) Periodic reevaluation of tobacco product standards"],[1,"The Secretary shall provide for periodic evaluation of tobacco product standards established under this section to determine whether such standards should be changed to reflect new medical, scientific, or other technological data. The Secretary may provide for testing under paragraph (4)(B) by any person."],[0,"(6) Involvement of other agencies; informed persons"],[1,"In carrying out duties under this section, the Secretary shall endeavor to—"],[2,"(A) use personnel, facilities, and other technical support available in other Federal agencies;"],[2,"(B) consult with other Federal agencies concerned with standard setting and other nationally or internationally recognized standard-setting entities; and"],[2,"(C) invite appropriate participation, through joint or other conferences, workshops, or other means, by informed persons representative of scientific, professional, industry, agricultural, or consumer organizations who in the Secretary's judgment can make a significant contribution."],[0,"(b) Considerations by Secretary"],[0,"(1) Technical achievability"],[1,"The Secretary shall consider information submitted in connection with a proposed standard regarding the technical achievability of compliance with such standard, including with regard to any differences related to the technical achievability of compliance with such standard for products in the same class containing nicotine not made or derived from tobacco and products containing nicotine made or derived from tobacco."],[0,"(2) Other considerations"],[1,"The Secretary shall consider all other information submitted in connection with a proposed standard, including information concerning the countervailing effects of the tobacco product standard on the health of adolescent tobacco users, adult tobacco users, or nontobacco users, such as the creation of a significant demand for contraband or other tobacco products that do not meet the requirements of this subchapter and the significance of such demand."],[0,"(c) Proposed standards"],[0,"(1) In general"],[1,"The Secretary shall publish in the Federal Register a notice of proposed rulemaking for the establishment, amendment, or revocation of any tobacco product standard."],[0,"(2) Requirements of notice"],[1,"A notice of proposed rulemaking for the establishment or amendment of a tobacco product standard for a tobacco product shall—"],[2,"(A) set forth a finding with supporting justification that the tobacco product standard is appropriate for the protection of the public health;"],[2,"(B) invite interested persons to submit a draft or proposed tobacco product standard for consideration by the Secretary;"],[2,"(C) invite interested persons to submit comments on structuring the standard so that it does not advantage foreign-grown tobacco over domestically grown tobacco; and"],[2,"(D) invite the Secretary of Agriculture to provide any information or analysis which the Secretary of Agriculture believes is relevant to the proposed tobacco product standard."],[0,"(3) Finding"],[1,"A notice of proposed rulemaking for the revocation of a tobacco product standard shall set forth a finding with supporting justification that the tobacco product standard is no longer appropriate for the protection of the public health."],[0,"(4) Comment"],[1,"The Secretary shall provide for a comment period of not less than 60 days."],[0,"(d) Promulgation"],[0,"(1) In general"],[1,"After the expiration of the period for comment on a notice of proposed rulemaking published under subsection (c) respecting a tobacco product standard and after consideration of comments submitted under subsections (b) and (c) and any report from the Tobacco Products Scientific Advisory Committee, the Secretary shall—"],[2,"(A) if the Secretary determines that the standard would be appropriate for the protection of the public health, promulgate a regulation establishing a tobacco product standard and publish in the Federal Register findings on the matters referred to in subsection (c); or"],[2,"(B) publish a notice terminating the proceeding for the development of the standard together with the reasons for such termination."],[0,"(2) Effective date"],[1,"A regulation establishing a tobacco product standard shall set forth the date or dates upon which the standard shall take effect, but no such regulation may take effect before 1 year after the date of its publication unless the Secretary determines that an earlier effective date is necessary for the protection of the public health. Such date or dates shall be established so as to minimize, consistent with the public health, economic loss to, and disruption or dislocation of, domestic and international trade. In establishing such effective date or dates, the Secretary shall consider information submitted in connection with a proposed product standard by interested parties, including manufacturers and tobacco growers, regarding the technical achievability of compliance with the standard, and including information concerning the existence of patents that make it impossible to comply in the timeframe envisioned in the proposed standard. If the Secretary determines, based on the Secretary's evaluation of submitted comments, that a product standard can be met only by manufacturers requiring substantial changes to the methods of farming the domestically grown tobacco used by the manufacturer, the effective date of that product standard shall be not less than 2 years after the date of publication of the final regulation establishing the standard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387g?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§387g. Tobacco product standards","tname":"Food and Drugs","by":{"1":"49, 49, 49, 49"}},{"t":"usc","label":"21 U.S.C. § 387r","url":"https://www.law.cornell.edu/uscode/text/21/387r","subs":["(b)(1)"],"by":{"1":"3"}},{"t":"reg","label":"1 C.F.R. § 18.12","url":"https://www.ecfr.gov/current/title-1/section-18.12","by":{"1":"47"}},{"t":"reg","label":"21 C.F.R. § 10.115","url":"https://www.ecfr.gov/current/title-21/section-10.115","subs":["(c)(1)","(g)"],"by":{"1":"48, 48"}},{"t":"reg","label":"21 C.F.R. § 1114.9","url":"https://www.ecfr.gov/current/title-21/section-1114.9","by":{"1":"41"}},{"t":"reg","label":"21 C.F.R. § 1143.1","url":"https://www.ecfr.gov/current/title-21/section-1143.1","by":{"1":"9"}},{"t":"reg","label":"FDA, Advance Notice of Proposed Rulemaking, Regulation of Flavors in Tobacco Products, 83 Fed. Reg. 12294","url":"https://www.govinfo.gov/link/fr/83/12294","by":{"1":"12"}},{"t":"reg","label":"FDA, Premarket Tobacco Product Applications and Recordkeeping Requirements, Final Rule, 86 Fed. Reg. 55300","url":"https://www.govinfo.gov/link/fr/86/55300","by":{"1":"24, 50"}},{"t":"case","label":"Atlantic Marine Construction Co. v. U.S. District Court","cite":"571 U.S. 49","y":2013,"id":"2013/12-929","sc":1,"op":1,"sum":"The Court held that the Federal Rules of Procedure allow two opposing parties in a lawsuit to transfer the litigation to a more convenient forum rather than being dismissed entirely.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"BMW of North America, Inc. v. Gore","cite":"517 U.S. 559","y":1996,"id":"1995/94-896","sc":1,"sum":"In a 5-to-4 decision, the Court held that while a state may impose punitive damages to further its interest in deterring unlawful conduct, the Fourteenth Amendment's due process clause prohibits states from imposing grossly excessive punishments on tort-feasors.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Erie-Lackawanna R.R. Co. v. United States","cite":"279 F. Supp. 316","y":1967,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./279/316/","by":{"2":"17"}},{"t":"case","label":"National Security Archive v. CIA","cite":"752 F.3d 460","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/752/460/","op":1,"by":{"2":"12"}},{"t":"case","label":"United States v. Chemical Foundation, Inc.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"United States v. Title Insurance & Trust Co.","cite":"265 U.S. 472","y":1924,"id":"scdb/1923-181","sc":1,"sum":"1. Where there are two grounds upon either of -which an appellate court may rest-its decision, and it adopts both, the ruling on neither is obiter dictum, but each is the judgment of the court, and of equal validity.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"2":"3"}}]};